],\"default_value\":\"now()\"}],\"primary_keys\":[\"id\"],\"foreign_key_constraints\":[{\"name\":\"objects_bucket_id_fkey\",\"source\":\"storage.objects.bucket_id\",\"target\":\"storage.buckets.id\"}]},{\"name\":\"storage.objects\",\"rls_enabled\":true,\"rows\":0,\"columns\":[{\"name\":\"bucket_id\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"name\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"owner\",\"data_type\":\"uuid\",\"format\":\"uuid\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"owner_id\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"metadata\",\"data_type\":\"jsonb\",\"format\":\"jsonb\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"id\",\"data_type\":\"uuid\",\"format\":\"uuid\",\"options\":[\"updatable\"],\"default_value\":\"gen_random_uuid()\"},{\"name\":\"user_metadata\",\"data_type\":\"jsonb\",\"format\":\"jsonb\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"path_tokens\",\"data_type\":\"ARRAY\",\"format\":\"_text\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"version\",\"data_type\":\"text\",\"format\":\"text\",\"options\":[\"nullable\",\"updatable\"]},{\"name\":\"created_at\",\"data_type\":\"timestamp with time zone\",\"format\":\"timestamptz\",\"options\":[\"nullable\",\"updatable\"],\"default_value\":\"now()\"},{\"name\":\"updated_at\",\"data_type\":\"timestamp with time zone\",\"format\":\"timestamptz\",\"options\":[\"nullable\",\"updatable\"],\"default_value\":\"now()\"},{\"name\":\"last_accessed_at\",\"data_type\":\"timestamp with time zone\",\"format\":\"timestamptz\",\"options\":[\"nullable\",\"updatable\"],\"default_value\":\"now()\"}],\"primary_keys\":[\"id\"],\"foreign_key_constraints\":[{\"name\":\"objects_bucket_id_fkey\",\"source\":\"storage.objects.bucket_id\",\"target\":\"storage.buckets.id\"}]}]}"
